const test = require("node:test");
const assert = require("node:assert");

const { HashRing } = require("./ring");

test("every key maps to a current node", () => {
  const ring = new HashRing(["a", "b", "c"], 50);
  for (let i = 0; i < 200; i++) {
    const node = ring.getNode(`key-${i}`);
    assert.ok(["a", "b", "c"].includes(node));
  }
});

test("deterministic", () => {
  const ring = new HashRing(["a", "b", "c"], 50);
  assert.strictEqual(ring.getNode("stable-key"), ring.getNode("stable-key"));
});

test("removing a node only moves that node's own keys", () => {
  const nodes = ["n0", "n1", "n2", "n3", "n4"];
  const ring = new HashRing(nodes, 100);
  const keys = Array.from({ length: 1000 }, (_, i) => `key-${i}`);
  const before = new Map(keys.map((k) => [k, ring.getNode(k)]));

  ring.removeNode("n2");
  const after = new Map(keys.map((k) => [k, ring.getNode(k)]));

  const moved = keys.filter((k) => before.get(k) !== after.get(k));
  assert.ok(moved.length > 0, "removing a node should move at least some keys");
  for (const k of moved) {
    assert.strictEqual(
      before.get(k),
      "n2",
      "only keys that were on the removed node may move",
    );
  }
  for (const k of keys) {
    assert.notStrictEqual(after.get(k), "n2");
  }
});

reference_solution.ring.js:
const crypto = require("node:crypto");

function hashInt(s) {
  return parseInt(crypto.createHash("md5").update(s).digest("hex").slice(0, 8), 16);
}

class HashRing {
  constructor(nodes, replicas = 100) {
    this.replicas = replicas;
    this.ring = new Map(); // point -> node
    this.sortedPoints = [];
    for (const node of nodes) {
      this.addNode(node);
    }
  }

  addNode(node) {
    for (let i = 0; i < this.replicas; i++) {
      this.ring.set(hashInt(`${node}:${i}`), node);
    }
    this.sortedPoints = [...this.ring.keys()].sort((a, b) => a - b);
  }

  removeNode(node) {
    for (let i = 0; i < this.replicas; i++) {
      this.ring.delete(hashInt(`${node}:${i}`));
    }
    this.sortedPoints = [...this.ring.keys()].sort((a, b) => a - b);
  }

  getNode(key) {
    if (this.ring.size === 0) {
      throw new Error("no nodes");
    }
    const point = hashInt(key);
    for (const p of this.sortedPoints) {
      if (p >= point) {
        return this.ring.get(p);
      }
    }
    return this.ring.get(this.sortedPoints[0]);
  }
}

module.exports = { HashRing };

